from h import build
R=[
(6017870,"Salade de pois chiches et de roquette",
"Cette recette associe simplement et délicieusement la roquette poivrée et la douceur des tomates séchées.\n\nTrouvez cette recette et bien d'autres dans The Diabetes Superfoods Cookbook and Meal Planner.",
"4","3/4 tasse",
["1 boîte (15,5 oz) de pois chiches (égouttés et rincés)","1/4 tasse de tomates séchées conservées dans l'huile d'olive et les herbes italiennes (égouttées)","1 gousse d'ail (hachée)","2 tasses de roquette"],
["Mélangez les pois chiches, les tomates égouttées et l'ail dans un saladier.","Incorporez la roquette. Laissez reposer 10 minutes pour que les feuilles de roquette flétrissent légèrement avant de servir."],[],[]),
(6018266,"Sorbet ananas-pêche",
"Le sorbet aux fruits est un dessert satisfaisant dont la douceur provient des sucres naturels des fruits, avec tous les nutriments et les fibres des fruits frais. Quand les fruits et légumes frais sont de saison, coupez et congelez les fruits vous-même. Sinon, vous trouverez un grand choix de fruits surgelés au rayon des surgelés de votre épicerie. Amusez-vous avec d'autres combinaisons de fruits comme mangue-fraise, pêche-framboise ou ananas-banane. Vous pouvez aussi verser le mélange dans des moules à bâtonnets glacés pour une gâterie parfaitement portionnée.",
"2","1/2 tasse",
["1/2 tasse de pêches surgelées","1/2 tasse de morceaux d'ananas surgelés","1/4 tasse de limonade sans sucre"],
["Mettez tous les ingrédients dans un mélangeur et mixez jusqu'à consistance lisse.","Versez le sorbet dans un contenant ou dans des moules à bâtonnets glacés et mettez-le immédiatement au congélateur."],[],[]),
(6018812,"Frites de patate douce",None,
"4","1/2 tasse",
["1 lb de patates douces (lavées, coupées en bâtonnets fins de 1/4 po)","1 1/2 cuillère à soupe d'huile d'olive","2 cuillères à café de fécule de maïs","1/2 cuillère à café de poudre d'ail","1/2 cuillère à café de paprika fumé","1/2 cuillère à café de poivre noir (fraîchement concassé)","1/4 cuillère à café de sel (de mer, ou plus au goût)"],
["Préchauffez le four à 425°F. Tapissez une plaque de cuisson de papier parchemin ou d'un tapis de silicone.","Rincez les patates douces sous l'eau froide courante jusqu'à ce que l'eau soit claire. Égouttez-les sur du papier absorbant et épongez-les. Séchez-les le mieux possible, puis transférez-les dans un grand bol.","Dans un petit bol, fouettez ensemble la fécule de maïs, la poudre d'ail, le paprika fumé, le poivre noir et le sel. Arrosez les patates douces d'huile d'olive et mélangez. Saupoudrez du mélange de fécule et remuez jusqu'à ce qu'elles soient bien enrobées. Transférez sur la plaque et disposez-les en une seule couche, en les espaçant le plus possible. Au besoin, utilisez une deuxième plaque (vos frites seront plus croustillantes).","Faites cuire 12 minutes. À l'aide d'une spatule, retournez les patates douces.","Goûtez et rectifiez l'assaisonnement au besoin. Servez chaud."],[],[]),
(6019263,"Margarine","Valeur nutritive de la margarine",
"1","1 cuillère à café",
["1 cuillère à café de margarine (en pot)"],[],[],[]),
(6019686,"Croustillant pommes-poires",
"Le croustillant pommes-poires est un dessert chaud et réconfortant qui allie la douceur naturelle des pommes et des poires à une garniture croquante d'avoine épicée. Cette recette est végétalienne et convient aux personnes diabétiques !",
"8","1/2 tasse",
["3 grosses pommes (pelées, évidées et tranchées)","3 grosses poires (pelées, évidées et tranchées)","1 cuillère à soupe de jus de citron","1/4 tasse de substitut de sucre pour la cuisson","1 cuillère à café de cannelle moulue","1/2 cuillère à café de muscade moulue","1/4 cuillère à café de sel","1/4 tasse de flocons d'avoine à l'ancienne","2 cuillères à soupe de farine tout usage","1 cuillère à soupe de substitut de cassonade","2 cuillères à soupe de beurre végétal (froid, en dés)"],
["Préchauffez le four à 350 degrés F. Graissez un plat de cuisson de 9 x 13.","Dans un grand bol, mélangez les pommes et les poires tranchées, le jus de citron, le sucre, la cannelle, la muscade et le sel. Remuez jusqu'à ce que les fruits soient bien enrobés et que le sucre et les épices soient répartis uniformément.","Dans un autre bol, mélangez l'avoine, la farine, le substitut de cassonade et le beurre végétal froid coupé en dés. Travaillez avec les mains ou un coupe-pâte jusqu'à ce que le mélange ressemble à de grosses miettes.","Étalez uniformément le mélange de fruits dans le plat préparé.","Parsemez le mélange d'avoine et de farine sur les fruits pour former une garniture friable.","Couvrez de papier d'aluminium et faites cuire 20 minutes. Retirez le papier d'aluminium et poursuivez la cuisson jusqu'à ce que le dessus soit doré et que les fruits bouillonnent, environ 20 minutes de plus.","Laissez refroidir 10 minutes avant de servir."],[],[]),
(6020482,"Tacos à la patate douce et aux haricots noirs",
"Les tacos à la patate douce et aux haricots noirs sont un plat végétarien délicieux et nutritif qui marie la douceur naturelle des patates douces et les haricots noirs riches en protéines. Essayez cette recette adaptée aux personnes diabétiques pour votre prochaine soirée tacos !",
"4","2 tacos",
["2 petites patates douces (pelées et coupées en dés)","2 cuillères à soupe d'huile d'olive (divisées)","1 cuillère à café de cumin moulu","1 cuillère à café de poudre de chili","1/2 cuillère à café de paprika fumé","2 gousses d'ail (hachées)","1 oignon rouge moyen (finement haché)","1 boîte (15 oz) de haricots noirs (sans sel ajouté, égouttés et rincés)","1/2 cuillère à café de sel casher","1/2 cuillère à café de poivre noir","8 petites tortillas de maïs","1/4 tasse de yogourt grec nature sans gras","1/4 tasse de mélange de fromages mexicains (réduit en gras)","1/4 tasse de coriandre fraîche (hachée)"],
["Préchauffez le four à 400 degrés F.","Dans un grand bol, mélangez les patates douces en dés avec 1 cuillère à soupe d'huile d'olive, le cumin moulu, la poudre de chili, le paprika fumé et l'ail haché jusqu'à ce qu'elles soient bien enrobées.","Étalez les patates douces assaisonnées sur une plaque de cuisson en une seule couche. Faites rôtir jusqu'à ce qu'elles soient tendres et légèrement croustillantes, environ 20 à 25 minutes. Remuez à mi-cuisson.","Pendant que les patates douces rôtissent, faites chauffer une poêle à feu moyen. Ajoutez 1 cuillère à soupe d'huile d'olive, puis faites sauter l'oignon rouge haché jusqu'à ce qu'il soit translucide.","Ajoutez les haricots noirs dans la poêle et mélangez-les avec les oignons. Poursuivez la cuisson de 3 à 5 minutes de plus, jusqu'à ce que les haricots soient chauds. Assaisonnez avec le sel casher et le poivre.","Réchauffez les tortillas de maïs dans une poêle sèche ou au micro-ondes.","Assemblez les tacos en déposant à la cuillère les patates douces rôties et le mélange de haricots noirs sur chaque tortilla.","Garnissez chaque taco de yogourt, de fromage et de coriandre."],[],[]),
(6020500,"Crevettes à la coriandre et à la lime",
"Ce plat rafraîchissant est faible en calories, riche en saveur et très polyvalent. Il peut être servi chaud ou froid, il est parfait pour un pique-nique (si vous pouvez le garder au frais ou s'il ne reste pas dehors trop longtemps), et peut aussi bien être roulé dans des tortillas que servi sur de la laitue ou du riz. Servez avec du sarrasin (kasha) et du brocoli vapeur assaisonné au citron-poivre.",
"4","1 1/2 tasse",
["1 cuillère à café d'huile d'olive extra vierge","1/2 cuillère à café d'ail (haché, environ 1 gousse)","1 lb de crevettes (grosses, décortiquées et déveinées, fraîches (jamais surgelées) si possible)","2 cuillères à soupe de jus de lime frais (ou plus au goût)","1/4 tasse de coriandre fraîche (hachée, ou plus au goût)","1/4 cuillère à café de sel","1/8 cuillère à café de poivre noir"],
["À FAIRE À L'AVANCE OU À DÉLÉGUER : Pelez l'ail, pressez la lime, hachez la coriandre, puis mélangez le jus de lime, la coriandre, le sel et le poivre.","(Commencez par le sarrasin et le brocoli si vous les servez.) Dans une grande poêle épaisse à feu moyen-vif, faites chauffer l'huile. Ajoutez l'ail et faites-le cuire environ 30 secondes, jusqu'à ce qu'il soit parfumé, puis ajoutez les crevettes et faites-les cuire en les retournant une fois, jusqu'à ce qu'elles soient roses et cuites à cœur, environ 2 à 3 minutes de chaque côté.","Transférez les crevettes dans un bol et mélangez-les avec le jus de lime, la coriandre, le sel et le poivre. Servez immédiatement ou réfrigérez jusqu'à 2 jours et servez froid.","POUR RELEVER LA SAVEUR : Doublez la quantité d'ail et saupoudrez le plat terminé de 1/2 cuillère à café de zeste de lime ou d'assaisonnement citron-poivre sans sel."],[],[]),
(6021641,"« Maïs soufflé » de chou-fleur",
"Croustillant et croquant, cette version originale du maïs soufflé est une délicieuse collation faible en glucides !",
"4","2/3 tasse",
["1 chou-fleur (coupé en petits bouquets)","2 cuillères à soupe d'huile d'olive","1/2 cuillère à café de poudre d'ail","1/2 cuillère à café de poudre d'oignon","1 cuillère à café de paprika fumé","1/4 cuillère à café de sel","1/4 cuillère à café de poivre noir","1/4 cuillère à café de piment de Cayenne (selon votre goût pour le piquant)"],
["Préchauffez le four à 425 degrés F et préparez une plaque de cuisson en la tapissant de papier parchemin ou en la graissant légèrement avec un enduit de cuisson en aérosol.","Prenez un chou-fleur et coupez-le en petits bouquets. Dans un grand bol, mélangez ces bouquets avec 2 cuillères à soupe d'huile d'olive, en vous assurant qu'ils sont bien enrobés.","Dans un autre bol, mélangez 1/2 cuillère à café de poudre d'ail, 1/2 cuillère à café de poudre d'oignon, 1 cuillère à café de paprika fumé, ½ cuillère à café de sel, ¼ cuillère à café de poivre noir et 1/4 cuillère à café de piment de Cayenne (selon votre goût pour le piquant).","Saupoudrez ce mélange d'épices sur le chou-fleur et remuez pour que les bouquets soient bien enrobés de ces assaisonnements savoureux.","Étalez le chou-fleur assaisonné en une seule couche sur la plaque préparée.","Faites cuire le chou-fleur au four préchauffé environ 20 à 25 minutes, jusqu'à ce que les bouquets soient tendres et légèrement croustillants. Pensez à remuer ou à secouer la plaque de temps en temps pour une cuisson uniforme.","Lorsque le « maïs soufflé » atteint le degré de croustillant désiré, sortez-le du four."],[],[]),
(6021807,"Courge spaghetti et sauce tomate au basilic",
"Cette courge spaghetti facile avec sa sauce tomate au basilic est une excellente option plus faible en glucides quand vous avez envie de pâtes. La courge spaghetti remplace très bien les nouilles et regorge de nutriments, ce qui en fait un choix santé pour toute la famille.",
"4","1 tasse",
["1 petite courge spaghetti","2 cuillères à soupe d'huile d'olive (divisées)","1/2 cuillère à café de sel casher (divisé)","1/2 cuillère à café de poivre noir","3 gousses d'ail (hachées)","28 oz de tomates concassées en conserve (faibles en sodium)","1 cuillère à café d'origan séché","2 cuillères à soupe de basilic frais (haché, plus des feuilles pour la garniture)"],
["Préchauffez le four à 375 degrés F.","Coupez la courge spaghetti en deux dans le sens de la longueur. Retirez les graines à la cuillère.","Placez les moitiés de courge, côté coupé vers le haut, sur une plaque de cuisson. Arrosez chaque moitié de 1/2 cuillère à soupe d'huile d'olive et assaisonnez de 1/2 cuillère à café de sel casher et de poivre noir.","Faites rôtir la courge spaghetti jusqu'à ce que la chair soit tendre et se détache facilement en filaments semblables à des spaghettis, environ 40 minutes.","Pendant que la courge rôtit, préparez la sauce tomate au basilic. Dans une casserole, faites chauffer 1 cuillère à soupe d'huile d'olive à feu moyen. Ajoutez l'ail haché et faites-le sauter jusqu'à ce qu'il soit parfumé.","Versez les tomates concassées, l'origan séché, le basilic, le sel casher et le poivre noir.","Laissez mijoter la sauce environ 15 à 20 minutes pour que les saveurs se marient.","Quand la courge spaghetti est cuite, utilisez une fourchette pour racler la chair en filaments semblables à des spaghettis.","Servez la courge spaghetti avec une généreuse louche de sauce tomate au basilic. Garnissez de basilic frais si désiré."],[],[]),
(6021884,"Saumon frotté au chipotle et au thé",
"Les mélanges d'épices à frotter sont simples à préparer et se conservent des semaines au réfrigérateur. Essayez ce mélange sur des fruits de mer, de la viande, de la volaille ou des légumes.",
"8","environ 127 g",
["4 piments chipotle entiers dans l'adobo","1 cuillère à soupe d'huile d'olive","1 cuillère à soupe de cassonade claire","1 cuillère à soupe de feuilles de thé moulues (vert ou noir)","1 cuillère à café d'origan séché","1 cuillère à café de sel casher","1 cuillère à soupe de jus de lime","2 lb de saumon rouge (sockeye) (sans la peau)"],
["Mettez tous les ingrédients, sauf le saumon, dans un mélangeur ou un robot culinaire et réduisez en purée lisse.","Frottez la surface du saumon avec ce mélange. Placez le saumon dans un plat de cuisson et laissez mariner 20 minutes.","Préchauffez le gril à feu moyen-vif. Vous pouvez cuire le saumon directement sur une feuille de papier d'aluminium ou le placer sur une grille perforée pour poissons ou légumes. Faites cuire à chaleur indirecte (loin de la source de chaleur) de 5 à 6 minutes de chaque côté. Le saumon est cuit lorsqu'un thermomètre à lecture instantanée indique 145 degrés F.","Laissez refroidir 30 minutes avant de servir."],[],[]),
(6022006,"Salade de lentilles",
"Il n'est pas nécessaire de faire tremper les lentilles sèches avant de les cuire. Cette recette rapide est donc prête en seulement 20 minutes.",
"6","1/2 tasse",
["1 tasse de lentilles (triées et rincées)","3 tasses d'eau","1 gousse d'ail (coupée en deux)","1 tige d'oignon vert (échalote) (tranchée)","1/2 tasse de poivron vert (en dés)","1 tasse de tomates raisins (coupées en deux)","1 citron moyen (pressé)","3 cuillères à soupe d'huile d'olive","1/4 cuillère à café de poivre noir","1/4 cuillère à café de persil (séché)"],
["Mettez les lentilles, l'eau et l'ail dans une casserole à feu moyen. Laissez mijoter 15 minutes, jusqu'à ce que les lentilles soient tendres. Égouttez les lentilles et rincez-les à l'eau froide. Jetez l'ail.","Pendant la cuisson des lentilles, fouettez ensemble les ingrédients de la vinaigrette.","Dans un saladier, mettez les lentilles, l'oignon vert, le poivron vert et les tomates. Arrosez les lentilles de vinaigrette et mélangez. Réfrigérez jusqu'au moment de servir."],[],[]),
(6023791,"Salade d'hiver de l'Action de grâce, vinaigrette au champagne",
"Égayez votre repas des fêtes avec cette salade colorée ! Le fromage bleu, les grenades et les noisettes apportent une saveur intéressante et du croquant à cette salade de saison, ce qui permet d'ajouter facilement plus de légumes à votre assiette des fêtes. Cette recette fait partie de notre plan de repas de l'Action de grâce adapté aux personnes diabétiques et a été modifiée pour donner 10 portions. La recette originale donne 6 portions et se trouve ici.",
"10","1 tasse",
["3 cuillères à soupe de vinaigre de champagne","2 cuillères à soupe de jus de citron","1 1/2 cuillère à café de miel","1/4 cuillère à café de sel","1/4 cuillère à café de poivre noir","3 cuillères à café de ciboulette fraîche (hachée)","1/3 tasse d'huile de noix ou d'olive","10 tasses de jeunes pousses de salade","3 cuillères à soupe plus 1 cuillère à café de fromage bleu (émietté)","1/3 tasse de graines de grenade","2 cuillères à soupe de noisettes (hachées)"],
["Dans un petit bol, fouettez ensemble le vinaigre de champagne, le jus de citron, le miel, le sel, le poivre, la ciboulette et l'huile jusqu'à ce que le tout soit bien mélangé. Ou mettez les ingrédients dans un bocal muni d'un couvercle hermétique et secouez jusqu'à ce qu'ils soient mélangés.","Dans un grand saladier, mélangez les jeunes pousses de salade, le fromage bleu, les graines de grenade et les noisettes. Remuez avec la vinaigrette juste avant de servir, ou servez la vinaigrette à part."],[],[]),
(6024065,"Piccata de poulet économique",
"La piccata de poulet est un classique de la cuisine italienne qui met en vedette les câpres salées et le citron frais. Le poulet est aplati et légèrement pané à la chapelure, ce qui le rend tendre et croustillant. Cette recette économique est rapide et facile à préparer. Servez-la sur un lit d'épinards, accompagnée de pâtes de blé entier, pour un souper italien léger.",
"4","1 poitrine de poulet et 1 cuillère à soupe de sauce",
["20 oz de poitrines de poulet désossées et sans peau","1/4 cuillère à café de sel","1/2 cuillère à café de poivre noir","1/4 tasse de farine de blé entier","1 œuf","1 jus de 1 citron","1/2 tasse de chapelure","1 cuillère à café d'assaisonnement italien","1 cuillère à café d'huile d'olive","2 cuillères à soupe de câpres (égouttées et rincées)","1/2 tasse de bouillon de poulet faible en sodium","1/4 tasse de persil frais haché"],
["Préchauffez le four à 475 degrés F. Vaporisez une plaque de cuisson d'enduit antiadhésif en aérosol et réservez.","Coupez les poitrines de poulet en deux dans le sens de la longueur, puis aplatissez-les à une épaisseur de 1/4 po. Assaisonnez chaque poitrine de sel et de poivre noir moulu.","Préparez trois grands bols ou contenants à fond plat. Mettez la farine de blé entier dans le premier bol, l'œuf et 1 cuillère à café de jus de citron dans le deuxième, et la chapelure et l'assaisonnement italien dans le troisième. Fouettez ensemble l'œuf et le jus de citron. Mélangez bien la chapelure et l'assaisonnement italien.","Roulez une poitrine de poulet dans la farine et secouez l'excédent. Trempez-la ensuite dans l'œuf, puis enrobez-la du mélange de chapelure. Placez-la sur la plaque de cuisson. Répétez avec les trois autres poitrines.","Vaporisez le dessus de chaque poitrine d'enduit antiadhésif et faites cuire 8 minutes. Retournez les poitrines et faites cuire 5 minutes de plus. Assurez-vous que le poulet a atteint une température interne de 165 degrés F.","Pendant la cuisson du poulet, faites chauffer l'huile et une bonne quantité d'enduit antiadhésif à feu moyen dans une petite poêle antiadhésive. Ajoutez les câpres et faites-les sauter 2 à 3 minutes.","Ajoutez environ 1 cuillère à soupe de jus de citron et faites cuire jusqu'à ce qu'il soit complètement réduit. Ajoutez le bouillon de poulet et laissez mijoter jusqu'à ce qu'il ait réduit de moitié. Incorporez le persil.","Sortez le poulet du four et servez-le arrosé de 1 cuillère à soupe de sauce."],[],[]),
(6024800,"Poulet rôti aux légumes et aux canneberges",
"Ce plat sain et adapté aux personnes diabétiques se prépare dans une seule casserole et constitue un délicieux repas de semaine. Cette recette, préparée avec des canneberges fraîches acidulées et d'autres légumes, est faible en glucides mais riche en vitamines, en nutriments et en saveur.",
"4","1 filet + environ 1/2 tasse de légumes",
["2 poitrines de poulet entières désossées et sans peau (coupées en fins filets)","1/4 cuillère à café de sel","1 cuillère à soupe d'huile d'olive (divisée)","1 oignon jaune moyen (en petits dés)","2 gousses d'ail (hachées)","1 cuillère à soupe de romarin frais (haché)","1 tasse de carottes (hachées)","1 1/2 cuillère à soupe de sirop d'érable","1/4 tasse de vinaigre de vin blanc","1 tasse de canneberges fraîches","1/4 tasse de persil plat (haché)"],
["Préchauffez le four à 400 degrés F.","Assaisonnez les poitrines de poulet de sel.","Faites chauffer une grande cocotte ou une grande poêle allant au four à feu moyen-vif. Ajoutez ½ cuillère à soupe d'huile d'olive, puis ajoutez le poulet. Faites-le saisir jusqu'à ce qu'il soit doré des deux côtés (sans être cuit à cœur). Retirez le poulet dans une assiette.","Remettez la poêle à feu moyen et ajoutez l'autre ½ cuillère à soupe d'huile. Ajoutez l'oignon, l'ail, le romarin et les carottes, et faites cuire jusqu'à ce que l'oignon soit translucide, environ 4 à 5 minutes.","Ajoutez le sirop et le vinaigre de vin blanc et faites cuire jusqu'à ce que le liquide ait réduit de moitié, environ 3 à 4 minutes. Incorporez les canneberges.","Remettez le poulet dans la poêle et disposez-le entre les légumes et les canneberges.","Couvrez avec un couvercle et faites cuire au four de 10 à 15 minutes, jusqu'à ce que le poulet soit cuit à cœur à une température interne de 165 degrés F et que les légumes soient tendres.","Servez avec une pincée de persil."],[],[]),
(6024876,"Wraps de laitue au poulet",
"Ces wraps de laitue au poulet sont un repas frais et facile, garni de poulet assaisonné et de légumes croquants. Cette recette est faible en glucides parce qu'elle utilise des feuilles de laitue à la place du pain.",
"6","1 wrap",
["2 tiges d'oignon vert (échalote) (tranchées finement)","6 carottes moyennes en julienne ou en bâtonnets","6 cuillères à café de sauce asiatique aux arachides","6 oz de poulet grillé (haché finement)","6 feuilles de laitue (la laitue Boston ou Bibb convient bien)"],
["Mélangez l'oignon vert, les carottes, la sauce aux arachides et le poulet dans un bol. Répartissez le mélange également entre 6 feuilles de laitue."],[],[]),
]
build(R,"out_xfr15_part1.json")
